def prepare():
    assert not RAW.exists() and not STAGE.exists();(QUEUE/'templates').mkdir(parents=True)
    import gen_assets as renderer
    renderer.TEMPLATES_DIR=QUEUE/'templates'
    for name in ['native_alpha','native_opaque']:
        (QUEUE/'templates'/(name+'.yaml')).write_text(yaml.safe_dump({'name':name,'prompt_template':'{asset_prompt}','size':'1536x1024','quality':'high','background':'opaque' if name=='native_opaque' else 'transparent'},sort_keys=False),'utf-8')
    rows=[];tasks=[]
    for key,(kind,label,detail) in ITEMS.items():
        opaque=kind=='ground'
        prompt=detail if opaque or kind=='npc_walk' else COMMON+detail
        if kind=='portrait':prompt='''Use case: stylized-concept
Create ONE waist-up matching NPC PORTRAIT of the SAME ordinary adult shown in the supplied map atlas identity reference. Portrait only, no atlas grid or extra people. Realistic painted wuxia RPG, softly lit ordinary face, modest practical everyday indigo clothing, transparent alpha0 outside complete head/shoulders/waist, generous empty border. Frontal three-quarter calm approachable expression, practical ordinary person rather than glamorous hero, same hair/face/clothes/jewelry as the map identity. No weapon, text, headdress, background scene or ground. Keep all hair, elbows and hem complete.
'''+detail
        template='native_opaque' if opaque else 'native_alpha';assert renderer.render_template(template,{'asset_prompt':prompt},{})['prompt']==prompt.strip()
        p=QUEUE/(key+'.txt');p.write_text(prompt,'utf-8')
        rows.append({'key':key,'kind':kind,'label':label,'id':NAME+'_'+key+'_v1','prompt':p.relative_to(ROOT).as_posix(),'prompt_sha256':sha(p),'transparent':not opaque,'calls':0,'status':'REGISTERED','model':None,'provider':None,'cost':None,'fallback_used':False})
        tasks.append({'id':NAME+'_'+key+'_v1','template':template,'skip':True,'execution_backend':'builtin_image_gen','attempt_budget':1,'retries_allowed':False,'cli_fallback_allowed':False,'vars':{'asset_prompt':prompt}})
    (QUEUE/'tasks.yaml').write_text(yaml.safe_dump({'tasks':tasks},allow_unicode=True,sort_keys=False),'utf-8')
    save(RAW/'manifest.json',{'status':'REGISTERED','backend':'builtin_image_gen','formal_enabled':False,'assets':rows})
    paths=[ROOT/'game/project.godot',ROOT/'game/scripts/autoload/scene_router.gd',ROOT/'prompts/tasks.yaml',ROOT/'scripts/gen_assets.py',ROOT/'game/scripts/field/player.gd',ROOT/'game/scenes/drafts/redrock_desert_complete_20261028d/redrock_town.tscn',ROOT/'game/scenes/drafts/desert_town_20261029d/desert_town.tscn',ROOT/'assets/raw/miao_town_design_20261029e/miao_masterplan_overview_v1.png']
    paths += [p for p in (Path(os.environ['APPDATA'])/'Godot/app_userdata/云影侠传').rglob('save*') if p.is_file()]
    save(STAGE/'protected-before.json',[{'path':str(p),'sha256':sha(p),'bytes':p.stat().st_size,'mtime_ns':p.stat().st_mtime_ns} for p in sorted(set(paths))])
    save(STAGE/'preflight.json',{'passed':True,'rendered':len(rows),'backend':'builtin_image_gen','root_queue_written':False,'no_fallback':True})
    save(STAGE/'approved-masterplan.json',{'user_quote':'可以，按照这个创造','design':'assets/raw/miao_town_design_20261029e/miao_masterplan_overview_v1.png','date':'2026-10-29','scope':'六区独立可编辑山城，不创建正式ID/剧情/奖励'})
    print('Registered22 native modules/atlases/portraits; renderer preflight passed; shared state protected')

def start(key):
    m=json.loads((RAW/'manifest.json').read_text('utf-8'));r=next(x for x in m['assets'] if x['key']==key)
    assert r['calls']==0 and r['status']=='REGISTERED' and sha(ROOT/r['prompt'])==r['prompt_sha256']
    r['calls']=1;r['status']='DISPATCHED';save(RAW/'manifest.json',m)
    print((ROOT/r['prompt']).read_text('utf-8'))

def record(key,source):
    m=json.loads((RAW/'manifest.json').read_text('utf-8'));r=next(x for x in m['assets'] if x['key']==key);assert r['status']=='DISPATCHED'
    source=Path(source);dest=RAW/r['kind']/(r['id']+'.png');dest.parent.mkdir(parents=True,exist_ok=True);assert not dest.exists();shutil.copyfile(source,dest)
    with Image.open(dest) as im:
        r.update(size=list(im.size),mode=im.mode)
        if r['transparent']:
            assert im.mode=='RGBA';b=im.getchannel('A').getbbox();w,h=im.size
            margins=[b[0]/w,b[1]/h,(w-b[2])/w,(h-b[3])/h];r['metrics']={'full_alpha_bbox':list(b),'margins':margins,'margin_10_percent_pass':min(margins)>=.1}
    assert sha(source)==sha(dest)
    r.update(output=dest.relative_to(ROOT).as_posix(),source_path=str(source),sha256=sha(dest),status='RAW_CANDIDATE',review_note='已确认苗风山城总规的独立原生组件；原PNG保持，留白/比例/遮挡/动画单独验收。')
    save(RAW/'manifest.json',m);save(dest.with_suffix('.meta.json'),r);save(RAW/'resource-pack.json',{'status':'NATIVE_EDITOR_CANDIDATES','assets':[x for x in m['assets'] if x.get('output')]})
    print(json.dumps({'key':key,'size':r['size'],'mode':r['mode'],'raw_A1_pass':r.get('metrics',{}).get('margin_10_percent_pass')}))

if __name__=='__main__':{'prepare':prepare,'start':lambda:start(sys.argv[2]),'record':lambda:record(sys.argv[2],sys.argv[3])}[sys.argv[1]]()
